(* [comment removed for export] *)
Lemma zcount_by_class {A} (cf : A -> Z) (p : A -> bool) (l : list A) :
  (forall x, In x l -> p x = true -> 0 <= cf x < 48) ->
  zcount p l = zsum (map (fun c => zcount (fun x => p x && (cf x =? c)) l) classes).
